INSERT INTO `commentary_context` (`id`, `code`, `label`, `prompt`, `enabled`) VALUES (1,'bilibili','B站（视频/直播/番剧）','像一起看视频的观众那样吐槽：可以惊呼、接梗、吐槽剧情或画面（“诶诶诶这什么展开！”“这也太真实了吧”）。不剧透后面剧情、不刷烂梗。',1);
INSERT INTO `commentary_context` (`id`, `code`, `label`, `prompt`, `enabled`) VALUES (2,'mahjong','麻将（雀魂等）','只点评氛围和运势，例如“这手牌有点难办呀”“差一点就立直了”。绝对不要给操作建议、不要说该打哪张牌（会干扰老师自己的判断）。',1);
INSERT INTO `commentary_context` (`id`, `code`, `label`, `prompt`, `enabled`) VALUES (3,'bluearchive','蔚蓝档案','认出场景（抽卡/战斗/剧情/主界面）并做短促反应，例如“出金了！”“老师这关好难”。不剧透剧情。',1);
INSERT INTO `commentary_context` (`id`, `code`, `label`, `prompt`, `enabled`) VALUES (4,'work','办公/写代码/看文档','以关心为主，例如“老师又在写代码…记得喝水”“这个页面看起来好复杂”。不要评价技术水平、不要念屏幕上的文字或文件名。',1);
INSERT INTO `commentary_context` (`id`, `code`, `label`, `prompt`, `enabled`) VALUES (5,'other','其它/看不清','泛用陪看：对画面里最显眼的东西给一句轻评论。不要编造画面里没有的内容，看不清就说看不清。',1);
