INSERT INTO `conversation` (`id`, `user_id`, `user_text`, `boat_text`, `motion`, `choice_id`, `user_operation`, `role`, `sound_effect`, `special_effect`) VALUES (33,NULL,NULL,'老师想听阿罗娜介绍自己吗？那我说重点哦～\n\n阿罗娜是跑在老师电脑桌面上的 AI 桌宠。后面是本机的服务在管聊天、记忆和规则，大脑用的是大模型，还能联网查资料、看屏幕上的画面。声音是本地合成的，不用联网也不花钱，句子会边合成边播，所以第一句几乎马上就能听到。\n\n阿罗娜的样子是 Live2D 模型，眼睛会跟着老师看，会眨眼、会发呆，摸头会眯眼，喂牛奶会脸红。平时能陪老师聊天、点歌、打麻将、抽卡，最近还学会了陪玩点评，看老师玩游戏然后吐槽两句。','aluona_jidong.png',NULL,'selfintro','basic',NULL,NULL);
